### __tests__/acceptance/m7-category-rename.test.ts
```ts
import { createStore, createMemoryRawStore, createMemoryKeyProvider } from '../../src/lib/storage/memory';
import { addReceipt, getAllReceipts } from '../../src/lib/receiptStore';
import {
  getAllCategories,
  renameCategory,
  isCategoryInUse,
  syncCategoriesWithReceipts,
} from '../../src/lib/categories';

describe('M7: renameCategory updates receipts case‑insensitively', () => {
  it('renames a default category and updates receipts that used the old name', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    // Add a receipt that uses the category in a different case
    await addReceipt(store, {
      id: 'r1',
      amount: 20,
      date: '2023-04-01',
      category: 'MEALS', // Upper‑case version of the default "Meals" category
      type: 'expense',
      notes: '',
    });

    // Verify the receipt is stored as written
    let receipts = await getAllReceipts(store);
    expect(receipts).toHaveLength(1);
    expect(receipts[0].category).toBe('MEALS');

    // Perform the rename (old name uses the proper case)
    await renameCategory(store, 'Meals', 'Food & Dining');

    // Ensure receipts have been updated to the new category name
    receipts = await getAllReceipts(store);
    expect(receipts).toHaveLength(1);
    expect(receipts[0].category).toBe('Food & Dining');

    // Sync categories with receipts to confirm the old name is not re‑added
    await syncCategoriesWithReceipts(store);

    // The old name must no longer appear in the category list (case‑insensitive check)
    const categories = await getAllCategories(store);
    const oldCat = categories.find((c) => c.name.toLowerCase() === 'meals');
    expect(oldCat).toBeUndefined();

    // The new name must be present
    const newCat = categories.find((c) => c.name === 'Food & Dining');
    expect(newCat).toBeDefined();

    // isCategoryInUse should now report true for the new name
    const inUse = await isCategoryInUse(store, 'Food & Dining');
    expect(inUse).toBe(true);
  });
});
```

### __tests__/acceptance/m7-mileage-decimal.test.ts
```ts
import { createStore, createMemoryRawStore, createMemoryKeyProvider } from '../../src/lib/storage/memory';
import { validateMileageMiles } from '../../src/lib/validation';
import { addMileageEntry, getAllMileageEntries } from '../../src/lib/mileageStore';
import { calculateMileageDeduction } from '../../src/lib/mileage';

describe('M7: mileage accepts decimal miles', () => {
  it('validates decimal mileage values', () => {
    // Valid cases (number and numeric string)
    expect(validateMileageMiles(12.5)).toBeNull();
    expect(validateMileageMiles('12.5')).toBeNull();

    // Invalid cases: too many decimals, non‑numeric text, zero/negative
    expect(validateMileageMiles(12.55)).not.toBeNull();
    expect(validateMileageMiles('abc')).not.toBeNull();
    expect(validateMileageMiles(0)).toBe('Miles must be > 0');
    expect(validateMileageMiles(-3)).toBe('Miles must be > 0');
  });

  it('stores and calculates deduction for a decimal mileage entry', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    const entry = {
      id: 'm2',
      date: '2023-05-01',
      miles: 12.5,
      purpose: 'Client visit',
    };
    await addMileageEntry(store, entry);

    const entries = await getAllMileageEntries(store);
    expect(entries).toHaveLength(1);
    // Stored miles should preserve the decimal value
    expect(entries[0].miles).toBeCloseTo(12.5);

    const rate = 0.585; // default IRS rate
    const deduction = calculateMileageDeduction(entry.miles, rate);
    // 12.5 miles * 0.585 = 7.3125
    expect(deduction).toBeCloseTo(7.3125, 4);
  });
});
```

