import {
  createStore,
  createMemoryRawStore,
  createMemoryKeyProvider,
} from '../../src/lib/storage/memory';
import {
  DEFAULT_CATEGORIES,
  getAllCategories,
  renameCategory,
  isCategoryInUse,
  syncCategoriesWithReceipts,
  addCustomCategory,
} from '../../src/lib/categories';
import { addReceipt } from '../../src/lib/receiptStore';
import { validateMileageMiles } from '../../src/lib/validation';

describe('Pinned existing behavior for categories and mileage validation', () => {
  // -----------------------------------------------------------------
  // getAllCategories
  // -----------------------------------------------------------------
  it('pinned: getAllCategories returns default categories with correct fields', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());
    const categories = await getAllCategories(store);
    const defaultEntries = categories.filter((c) => !c.custom);
    expect(defaultEntries).toHaveLength(DEFAULT_CATEGORIES.length);

    const meals = categories.find((c) => c.id === 'Meals');
    expect(meals).toBeDefined();
    expect(meals?.name).toBe('Meals');
    expect(meals?.hidden).toBe(false);
    expect(meals?.custom).toBe(false);
  });

  // -----------------------------------------------------------------
  // renameCategory (success cases)
  // -----------------------------------------------------------------
  it('pinned: renameCategory successfully renames a default category and is reflected in getAllCategories', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());
    const result = await renameCategory(store, 'Meals', 'Food & Dining');
    expect(result).toBeNull();

    const categories = await getAllCategories(store);
    const renamed = categories.find((c) => c.id === 'Meals');
    expect(renamed).toBeDefined();
    expect(renamed?.name).toBe('Food & Dining');

    // The number of default entries must stay unchanged.
    const defaultCount = categories.filter((c) => !c.custom).length;
    expect(defaultCount).toBe(DEFAULT_CATEGORIES.length);
  });

  it('pinned: renameCategory updates a custom category name correctly', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    // create a custom category
    const addResult = await addCustomCategory(store, 'Travel');
    expect(addResult).toBeNull();

    // rename it
    const renameResult = await renameCategory(store, 'Travel', 'Journeys');
    expect(renameResult).toBeNull();

    const categories = await getAllCategories(store);
    // old name should no longer exist
    const oldCat = categories.find((c) => c.id === 'Travel' || c.name === 'Travel');
    expect(oldCat).toBeUndefined();

    // new name should exist and be marked as custom
    const newCat = categories.find((c) => c.id === 'Journeys' && c.custom);
    expect(newCat).toBeDefined();
    expect(newCat?.name).toBe('Journeys');
    expect(newCat?.custom).toBe(true);
  });

  // -----------------------------------------------------------------
  // renameCategory (failure cases)
  // -----------------------------------------------------------------
  it('pinned: renameCategory rejects an invalid new name and leaves categories unchanged', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    const error = await renameCategory(store, 'Meals', '');
    expect(error).toBe('Category must be 1‑40 characters and not contain < or >.');

    const categories = await getAllCategories(store);
    const meals = categories.find((c) => c.id === 'Meals');
    expect(meals?.name).toBe('Meals');
  });

  it('pinned: renameCategory rejects a duplicate new name (case‑insensitive) and does not modify categories', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    const error = await renameCategory(store, 'Meals', 'Vehicle & fuel');
    expect(error).toBe('Category already exists.');

    const categories = await getAllCategories(store);
    const meals = categories.find((c) => c.id === 'Meals');
    expect(meals?.name).toBe('Meals');
  });

  it('pinned: renameCategory returns an error when the original category does not exist and leaves data untouched', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    const error = await renameCategory(store, 'Nonexistent', 'NewName');
    expect(error).toBe('Category not found.');

    const categories = await getAllCategories(store);
    const hasNew = categories.some((c) => c.name === 'NewName');
    expect(hasNew).toBe(false);
  });

  // -----------------------------------------------------------------
  // isCategoryInUse
  // -----------------------------------------------------------------
  it('pinned: isCategoryInUse detects usage case‑insensitively', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    await addReceipt(store, {
      id: 'r1',
      amount: 10,
      date: '2023-01-01',
      category: 'MEALS',
      type: 'expense',
      notes: '',
    });

    const inUse = await isCategoryInUse(store, 'Meals');
    expect(inUse).toBe(true);
  });

  it('pinned: isCategoryInUse returns false when the category is not used by any receipt', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    const inUse = await isCategoryInUse(store, 'Travel');
    expect(inUse).toBe(false);
  });

  // -----------------------------------------------------------------
  // syncCategoriesWithReceipts
  // -----------------------------------------------------------------
  it('pinned: syncCategoriesWithReceipts adds a custom category for a receipt with an unknown category', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    await addReceipt(store, {
      id: 'r1',
      amount: 20,
      date: '2023-01-01',
      category: 'Travel Concierge',
      type: 'expense',
      notes: '',
    });

    await syncCategoriesWithReceipts(store);

    const categories = await getAllCategories(store);
    const custom = categories.find((c) => c.name === 'Travel Concierge');
    expect(custom).toBeDefined();
    expect(custom?.custom).toBe(true);
  });

  it('pinned: syncCategoriesWithReceipts does not add a custom category when the receipt category matches a default (case‑insensitive)', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    await addReceipt(store, {
      id: 'r2',
      amount: 15,
      date: '2023-01-02',
      category: 'meals', // lower‑case version of a default
      type: 'expense',
      notes: '',
    });

    await syncCategoriesWithReceipts(store);

    const categories = await getAllCategories(store);
    // No custom entry should have been created for "meals"
    const hasCustom = categories.some((c) => c.custom && c.name.toLowerCase() === 'meals');
    expect(hasCustom).toBe(false);
  });

  it('pinned: syncCategoriesWithReceipts ignores receipt categories that fail validation (e.g., contain <)', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    await addReceipt(store, {
      id: 'r3',
      amount: 5,
      date: '2023-01-03',
      category: '<Invalid>',
      type: 'expense',
      notes: '',
    });

    await syncCategoriesWithReceipts(store);

    const categories = await getAllCategories(store);
    const hasInvalid = categories.some((c) => c.name === '<Invalid>');
    expect(hasInvalid).toBe(false);
  });

  // -----------------------------------------------------------------
  // validateMileageMiles
  // -----------------------------------------------------------------
  it('pinned: validateMileageMiles accepts a valid integer number of miles', () => {
    expect(validateMileageMiles(1)).toBeNull();
    expect(validateMileageMiles('123')).toBeNull();
  });

  it('pinned: validateMileageMiles rejects zero or negative values', () => {
    expect(validateMileageMiles(0)).toBe('Miles must be > 0');
    expect(validateMileageMiles(-5)).toBe('Miles must be > 0');
  });

  it('pinned: validateMileageMiles rejects non‑integer values (including decimal strings)', () => {
    expect(validateMileageMiles(12.5)).toBe('Miles must be > 0');
    expect(validateMileageMiles('12.5')).toBe('Miles must be > 0');
  });

  it('pinned: validateMileageMiles rejects values greater than 10,000', () => {
    expect(validateMileageMiles(10001)).toBe('Miles must be ≤ 10,000');
  });
});
